mapper.select:
SELECT b.target_id AS targetId,
       COUNT(a.id) AS count
FROM source_binding b
JOIN source_attachment a
  ON a.source_id = b.source_id
WHERE b.clan_id = #{clanId}
  AND b.target_type = #{targetType}
  AND b.target_id IN

    #{id}

  AND b.binding_status <> #{excludedStatus}
  AND a.deleted_at IS NULL
GROUP BY b.target_id
